export interface Transaction {
  id: number;
  date: string;
  amount_agorot: number;
  category_id: number | null;
  payment_method_id: number | null;
  note: string;
  sync_state: string;
  /** Set on a settled occurrence of a repeating transaction (a stored row). */
  recurring_series_id?: number | null;
  /** Client-side only: an unsettled occurrence, generated by the server, not yet a stored row. */
  upcoming?: boolean;
  recurring_segment_id?: number;
}

/** One rule of a repeating monthly transaction; a series is one or more segments. */
export interface RecurringSegment {
  id: number;
  series_id: number;
  start_month: string;
  end_month: string | null;
  day: number;
  amount_agorot: number;
  category_id: number | null;
  payment_method_id: number | null;
  note: string;
}

export type NewRecurring = Omit<RecurringSegment, "id" | "series_id">;

export interface Occurrence {
  series_id: number;
  segment_id: number;
  date: string;
  amount_agorot: number;
  category_id: number | null;
  payment_method_id: number | null;
  note: string;
}

export interface Category {
  id: number;
  name: string;
  is_income: boolean;
  parent_id: number | null;
  /** Came from Paamonim: a Paamonim category, or an item there for a sub-category. */
  from_paamonim: boolean;
  /** On a top-level category made here: the Paamonim top-level category it stands in for. */
  linked_to: number | null;
}

/** One business of the whole business; the general one holds costs shared by the others. */
export interface Business {
  id: number;
  name: string;
  is_general: boolean;
}

/** Which transactions (tags) and categories count in which business, as [id, business id] pairs. */
export interface BusinessData {
  businesses: Business[];
  links: { transactions: [number, number][]; categories: [number, number][] };
}

export interface MonthlyTotal {
  month: string;
  category_id: number | null;
  total_agorot: number;
  count: number;
}

export interface ImportSummary {
  categories_added: number;
  payment_methods_added: number;
  transactions_added: number;
  transactions_skipped: number;
}

/** One recorded change. `old`/`new` are snapshots (names, not ids) and depend on `kind`. */
export interface LogEntry {
  id: number;
  /** UTC, ISO 8601. */
  at: string;
  kind: string;
  entity_id: number | null;
  old: Record<string, unknown> | null;
  new: Record<string, unknown> | null;
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, { cache: "no-store", headers: { "Content-Type": "application/json" }, ...init });
  if (!res.ok) throw new Error(await res.text());
  return res.status === 204 ? (undefined as T) : res.json();
}

export const api = {
  /** Change log, newest first; pass the last id of the previous page as `beforeId` for the next. */
  log: (beforeId?: number, limit = 100) =>
    request<LogEntry[]>(`/api/log?limit=${limit}${beforeId != null ? `&before_id=${beforeId}` : ""}`),
  transactions: () => request<Transaction[]>("/api/transactions"),
  categories: () => request<Category[]>("/api/categories"),
  monthlyTotals: () => request<MonthlyTotal[]>("/api/monthly-totals"),
  addTransaction: (t: Omit<Transaction, "id" | "sync_state">) =>
    request<number>("/api/transactions", { method: "POST", body: JSON.stringify(t) }),
  recurring: () => request<RecurringSegment[]>("/api/recurring"),
  occurrences: () => request<Occurrence[]>("/api/recurring/occurrences"),
  addRecurring: (r: NewRecurring) => request<number>("/api/recurring", { method: "POST", body: JSON.stringify(r) }),
  /** Apply `r` from `r.start_month` on; earlier months keep their values. */
  changeRecurring: (series: number, r: NewRecurring) =>
    request<void>(`/api/recurring/${series}`, { method: "PUT", body: JSON.stringify(r) }),
  /** Edit one month on its own (month is YYYY-MM): it becomes a transaction; the series is unchanged. */
  settleRecurringMonth: (series: number, month: string, t: Omit<Transaction, "id" | "sync_state">) =>
    request<void>(`/api/recurring/${series}/months/${month}`, { method: "POST", body: JSON.stringify(t) }),
  /** Skip one month (YYYY-MM); the series is unchanged. */
  skipRecurringMonth: (series: number, month: string) =>
    request<void>(`/api/recurring/${series}/months/${month}`, { method: "DELETE" }),
  /** Stop the series from this month (YYYY-MM) on. */
  cancelRecurring: (series: number, from: string) =>
    request<void>(`/api/recurring/${series}?from=${from}`, { method: "DELETE" }),
  importPaamonim: (from: string, to: string) =>
    request<ImportSummary>("/api/import/paamonim", { method: "POST", body: JSON.stringify({ from, to }) }),
  addCategory: (c: { name: string; is_income: boolean; parent_id: number | null; linked_to?: number | null }) =>
    request<number>("/api/categories", { method: "POST", body: JSON.stringify(c) }),
  /** Link a top-level category made here to a Paamonim top-level category. */
  linkCategory: (id: number, linkedTo: number | null) =>
    request<void>(`/api/categories/${id}/link`, { method: "PUT", body: JSON.stringify({ linked_to: linkedTo }) }),
  /** Move a sub-category, with its transactions, under another top-level category. */
  moveCategory: (id: number, parentId: number) =>
    request<void>(`/api/categories/${id}/move`, { method: "POST", body: JSON.stringify({ parent_id: parentId }) }),
  /** Also deletes sub-categories; their transactions move to `moveTo` (required if there are any). */
  deleteCategory: (id: number, moveTo?: number) =>
    request<number>(`/api/categories/${id}${moveTo != null ? `?move_to=${moveTo}` : ""}`, { method: "DELETE" }),
  businesses: () => request<BusinessData>("/api/businesses"),
  addBusiness: (name: string, isGeneral: boolean) =>
    request<number>("/api/businesses", { method: "POST", body: JSON.stringify({ name, is_general: isGeneral }) }),
  renameBusiness: (id: number, name: string) =>
    request<void>(`/api/businesses/${id}`, { method: "PUT", body: JSON.stringify({ name }) }),
  deleteBusiness: (id: number) => request<void>(`/api/businesses/${id}`, { method: "DELETE" }),
  /** Make a category's transactions count in a business (null removes the link). */
  linkCategoryBusiness: (category: number, business: number | null) =>
    request<void>(`/api/categories/${category}/business`, { method: "PUT", body: JSON.stringify({ business_id: business }) }),
  /** Tag transactions as a business's (null removes their tags). */
  tagTransactions: (ids: number[], business: number | null) =>
    request<void>("/api/businesses/tag", { method: "PUT", body: JSON.stringify({ ids, business_id: business }) }),
  exportSheets: () => request<{ transactions: number; tabs: number }>("/api/export/sheets", { method: "POST" }),
  updateTransaction: (id: number, t: Omit<Transaction, "id" | "sync_state">) =>
    request<void>(`/api/transactions/${id}`, { method: "PUT", body: JSON.stringify(t) }),
  deleteTransaction: (id: number) => request<void>(`/api/transactions/${id}`, { method: "DELETE" }),
  /** Whether changes are being written to Paamonim. */
  mirrorStatus: () => request<{ enabled: boolean }>("/api/mirror/status"),
};

/** Parse a user-typed shekel amount ("12.5") into exact agorot. */
export function parseAgorot(input: string): number {
  const n = Number(input.replace(",", "."));
  if (!Number.isFinite(n)) throw new Error("Invalid amount");
  return Math.round(n * 100);
}

export function formatShekels(agorot: number): string {
  return (agorot / 100).toLocaleString("he-IL", { style: "currency", currency: "ILS" });
}
